const d=[{id:"stoic-epictetus-iep",title:"S09 · Seddon · Epiktet · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epiktets Unterscheidung zwischen dem, was bei uns liegt, und dem, was nicht bei uns liegt, richtet die Anstrengung philosophisch auf Urteile, Ziele und Verhalten.",limitation:"Geschichte und Philosophie, kein psychologischer Beleg für vollständig willentliche Gedanken oder Handlungen. Behinderung, Krankheit, Zwang und verfügbare Mittel begrenzen das Handeln."},{id:"stoic-seneca-iep",title:"S10 · Wagoner · Seneca · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Senecas philosophische Beschreibung von Zorn unterscheidet unwillkürliche erste Regungen von späterer Zustimmung.",limitation:"Historische Philosophie, kein bestätigtes vollständiges Modell von Gefühlen. Panik oder Traumasymptome lassen sich deshalb nicht einfach abwählen und sind kein moralisches Versagen."},{id:"stoic-week-handbook",title:"S08 · Stoicism Today · Handbuch zur Stoic Week 2016",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"Beschreibt die Unterscheidung nach Einfluss, das Nachdenken über Widrigkeiten, einen weiteren Blick und einen fairen Abendrückblick von fünf bis zehn Minuten vor dem Zubettgehen.",limitation:"Ein Praxishandbuch, keine Studie zu einzelnen Ritualen oder optimaler Dauer. Keine bestätigte unabhängige Wirkung für Sortieren nach Einfluss, negative Bilder, kosmische Perspektive oder Abendrückblick."},{id:"stoic-planning",title:"S03 · Gollwitzer und Sheeran · 2006 · Wenn-dann-Pläne",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 unabhängige Untersuchungen mit 8.461 Teilnehmenden fanden durchschnittliche Vorteile für Zielerreichung durch konkrete Situation-Reaktion-Pläne: d = 0,65 [0,60; 0,70].",limitation:"Unterschiedliche Ziele, Designs und Vergleiche. Nicht nur moderne vorregistrierte randomisierte Studien. Das ist weder eine Erfolgsquote noch eine Garantie oder ein Beleg für negative Zukunftsbilder."},{id:"stoic-mcii",title:"S04 · Wang, Wang und Gai · 2021 · Mentales Kontrastieren mit Planung",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 Artikel lieferten 24 unabhängige Schätzungen mit 15.907 Teilnehmenden. Gewünschtes Ergebnis, heutiges Hindernis und Wenn-dann-Reaktion ergaben durchschnittlich g = 0,336 [0,229; 0,443] für Zielerreichung.",limitation:"Erhebliche Unterschiede, I² = 59,3%, und uneinheitliche Qualität begrenzen die Genauigkeit. Das prüft weder negative Bilder allein noch die Machbarkeit aller Ziele oder ODAs kurze Anpassung."},{id:"stoic-thought-record",title:"S11 · NHS · Gedankenprotokoll · Every Mind Matters",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/thought-record/",type:"guidance",finding:"Sieben Fragen trennen Situation, Gefühle, Gedanken, Belege dafür, Belege dagegen, eine realistische Alternative und Gefühle danach. Auch eine neutrale Schlussfolgerung kann passen.",limitation:"Offizielle Selbsthilfeempfehlung, keine Studie zur einzelnen Effektgröße. Sie verlangt weder Positivität noch, tatsächliche Misshandlung als harmlos zu deuten."},{id:"stoic-cbt",title:"S01 · Hofmann und andere · 2012 · Überblick über Metaanalysen zur kognitiven Verhaltenstherapie",url:"https://www.europsy.net/app/uploads/2017/08/Hofmann-2012-The-efficacy-of-CBT-a-review-of-meta-analyses.pdf",type:"research",finding:"Die Autoren fanden 269 Metaanalysen und besprachen 106 repräsentative Arbeiten. Für mehrere angstbezogene Störungen, Zorn und Stress gab es starke, störungsspezifische Belege.",limitation:"Ein beschreibender Überblick ohne gemeinsame Effektgröße oder Teilnehmerzahl für die gesamte kognitive Verhaltenstherapie. Behandlungsbelege gelten weder für eine stoische Lektion noch für ein kurzes Gedankenprotokoll allein."},{id:"stoic-kross-self-talk",title:"S05 · Kross und andere · 2014 · Selbstgespräche zur Selbstregulation",url:"https://rascl.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Sieben Studien mit insgesamt 585 Teilnehmenden untersuchten Nachdenken außerhalb der Ich-Form. Studie 1a nutzte 60 Sekunden Reflexion. Danach berichteten Teilnehmende mehr Abstand zu sich selbst.",limitation:"Experimente eines Forschungsprogramms, deren Ergebnisse in dieselbe Richtung weisen, keine sieben unabhängigen klinischen Studien. Den eigenen Namen zu nutzen ist keine nachgewiesene Behandlung. ODAs milde Übung zur aktuellen Situation ist eine Anpassung."},{id:"stoic-kross-distancing",title:"S06 · Murdoch und andere · 2023 · Metaanalyse zu Reflexion mit Abstand",url:"https://onlinelibrary.wiley.com/doi/full/10.1002/smi.3199",type:"research",finding:"25 Experimente in 17 Artikeln mit 2.397 Teilnehmenden fanden über verschiedene Ergebnisse einen mäßigen Gesamteffekt: g = 0,19 [0,05; 0,33].",limitation:"Überwiegend junge, offenbar gesunde Erwachsene. Unklare Qualität und erhebliche Unterschiede. Das Vorhersageintervall schloss null ein. Für objektive Ergebnisse gab es keine statistisch signifikanten Effekte. Kosmische oder Zehnjahresrituale wurden nicht einzeln geprüft."},{id:"stoic-distancing-sleep",title:"S16 · Riddell und andere · 2023 · Über Belastungen nachdenken und Schlaf",url:"https://onlinelibrary.wiley.com/doi/10.1002/smi.3201",type:"research",finding:"Ein vorregistriertes Reflexionsexperiment stützte keinen Schlafvorteil durch Abstand. Die Veränderung der Schlafqualität fiel zugunsten der Ich-Perspektive aus. Der Unterschied in der Schlafdauer war nicht signifikant.",limitation:"318 Teilnehmende zu Beginn, 257 ausgewertet. 51 aus der Abstandsgruppe wurden wegen Schreiben in der Ich-Form ausgeschlossen. Widersprüchliche Vorzeichen in Tabelle und Text erlauben keine Richtungsaussage zum Wohlbefinden."},{id:"stoic-training-trial",title:"S13 · Maclellan und Derakshan · 2021 · Training bei ausgeprägten Sorgen",url:"https://link.springer.com/article/10.1007/s10608-020-10183-4",type:"research",finding:"45 Menschen mit starken Sorgen wurden zufällig einem stoischen Training mit acht Einheiten, einem kombinierten Training oder einer aktiven One-back-Kontrolle zugeordnet. Die Zusammenfassung berichtet Veränderungen bei Grübeln und Selbstwirksamkeit.",limitation:"Eine kleine Studie, hier nur als Zusammenfassung zugänglich. Genaue Effekte, Konfidenzintervalle, Ausfälle und Vorregistrierung wurden nicht bestätigt. Sie prüft kein einzelnes Ritual und belegt keine Behandlung diagnostizierter Angst."},{id:"stoic-training-thesis",title:"S15 · King · 2025 · Dissertation zu modernem Stoizismus und psychischer Gesundheit",url:"https://pure.royalholloway.ac.uk/en/publications/modern-stoicism-and-mental-health-a-randomised-controlled-trial/",type:"research",finding:"119 Erwachsene aus einer nichtklinischen Stichprobe wurden einem zweiwöchigen stoischen Onlinetraining oder einer Warteliste zugeteilt. Die Hochschulzusammenfassung berichtet günstige Veränderungen bei einigen Messwerten zur psychischen Gesundheit bei Teilnehmenden mit vollständigen Daten.",limitation:"Eine unveröffentlichte Dissertation, kein fachlich begutachteter Konsens zur Wirksamkeit. Abschlusszahlen, Effekte, Intervalle und Registrierung blieben ungeprüft. Ein Wartelistenvergleich belegt weder einzelne Ritualwirkungen noch Gleichwertigkeit mit Psychotherapie."}],a=[{schemaVersion:2,revision:2,id:"stoic-1",courseId:"stoic",locale:"de",title:"Wieder ins Postfach geschaut? Die Antwort bestimmst du nicht.",goal:"Erstelle etwas Nützliches für dein gewähltes Ziel, während sein Ausgang noch offen bleibt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Schon wieder nach der Antwort geschaut? Gib einem Schritt, der deinem Ziel helfen könnte, etwas von dieser Aufmerksamkeit.",reason:{id:"stoic-1-reason",label:"Welcher nützliche Schritt blieb durchs Nachschauen liegen?",kind:"text",maxLength:160,optional:!0,suggestions:["Ein konkretes Beispiel für meine Arbeit liefern","Nicht zur Beruhigung nachschauen","Um praktische Hilfe bitten"]},why:{id:"stoic-1-why",label:"Welcher nützliche Schritt blieb durchs Nachschauen liegen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ein Ergebnis darf dir wichtig sein, auch wenn du es nicht bestimmen kannst. Epiktet nutzte diese Unterscheidung, um Anstrengung auf Verhalten statt auf Ansehen oder Ergebnisse zu richten. Das ist Philosophie. Sie beweist nicht, dass jeder Gedanke und jede Handlung ganz willentlich sind. Gesundheit, Zwang, Behinderung und verfügbare Mittel können dich begrenzen.","Wähle für deinen Versuch im Lauf dieses Kurses ein Ziel und einen nützlichen Schritt. Trenne, was du versuchen kannst, wo du Unterstützung brauchst und was andere entscheiden. Dann setze deinen machbaren Teil um. Ein Satz für die Arbeitsprobe ist da, auch wenn kein Arbeitgeber antwortet. Nutze Ergebnisse als Hinweise. Du musst nicht aufhören, sie wichtig zu finden."],example:{title:"Daniels Satz über ein Projektergebnis",text:"Am Montagmittag hat Daniel sein Bewerbungspostfach schon viermal aktualisiert. Er möchte ein konkretes Beispiel für seine Projektarbeit in der Bewerbung zeigen. Am Schreibtisch schreibt er einen konkreten Satz für seine Arbeitsprobe: Welche Checkliste hat er verbessert und wie wurde sie genutzt? Er hält den Satz fest. Das Postfach bleibt leer. Er fühlt sich weiterhin unsicher."}},move:{invitation:"Wähle einen nützlichen Schritt, während das Ergebnis offen bleibt.",instructions:["Trenne Schritt, nötige Unterstützung und Ergebnis. Verlange keine vollständige Kontrolle.","Setze deinen machbaren Teil um und halte ihn fest."],prompts:[],suggestions:{action:["Ein passendes Projektergebnis in einem Satz beschreiben","Eine passende Frage zur Klärung senden","Um praktische Unterstützung bitten"],minimum:["Ein Projektergebnis in einem brauchbaren Satz beschreiben","Eine klare Frage senden","Eine konkrete Bitte um Unterstützung äußern"],cue:["Wenn ich vom Mittagessen zurückkomme","Bei meiner nächsten sicheren Gelegenheit","Vor dem nächsten Projektschritt"],place:["An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf","An einem für mich zugänglichen Ort zum Planen"],minutes:[2,5],fallback:["Den Satz als Sprachnotiz festhalten","Einen kleineren passenden Beitrag wählen","Um Hilfe beim Zugang bitten"],observation:["Das nützliche Ergebnis meiner Arbeit","Meine Frage und eine mögliche Antwort","Um welche Unterstützung ich gebeten habe"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Ein passendes Projektergebnis in einem Satz beschreiben",minimum:"Ein Projektergebnis in einem brauchbaren Satz beschreiben",minutes:2,cueHint:"Wenn ich vom Mittagessen zurückkomme",placeHint:"An meinem gewohnten Arbeitsplatz",obstacleHint:"Meine verfügbare Kraft oder meine Mittel sind begrenzt.",fallbackHint:"Den Satz als Sprachnotiz festhalten",observationHint:"Das nützliche Ergebnis meiner Arbeit"},stopRule:"Übe nicht in Gefahr weiter. Such Schutz oder Unterstützung, wenn dein Handeln eingeschränkt ist.",accessibleAlternative:"Nutze Diktieren, unterstützte Kommunikation, eine sichere Grenze oder praktische Unterstützung."},result:{question:"Hast du dein machbares Minimum umgesetzt?",observationPrompt:"Was hast du erstellt oder gefragt? Was bleibt noch offen?"},judgment:{primary:{id:"stoic-1-decision",scenario:"Daniel hat nach dem Mittagessen zehn Minuten. Es steht keine dringende Antwort aus. Sein Bewerbungseinstieg ist klar. Eine Personalverantwortliche hat aber nach konkreten Beispielen für seine Projektarbeit gefragt. Er hat ein passendes Beispiel, das er beschreiben kann.",question:"Wofür sollte er diese Minuten nutzen?",options:[{id:"keep-checking",text:"Alle paar Minuten das Postfach prüfen, damit ein möglicher Arbeitgeber sofort eine Antwort bekommt.",feedback:"Erreichbar zu sein kann wichtig sein. Hier wird keine dringende Antwort erwartet. Ein nützlicher Beleg lässt sich erstellen. Wähle eine Zeit fürs Nachschauen und gib jetzt dem Satz Platz."},{id:"write-evidence",text:"Jetzt ein passendes Projektergebnis in einem Satz beschreiben und das Postfach danach zu einer gewählten Zeit prüfen.",feedback:"Das investiert in einen machbaren Schritt, ohne ein Angebot zu versprechen. Halte den Satz fest. Behalte nötige Erreichbarkeit und behandle eine spätere Antwort als Hinweis."},{id:"revise-opening",text:"Zehn Minuten den ersten Absatz überarbeiten, damit die Bewerbung sein Projekt klarer präsentiert.",feedback:"Ein klarerer Einstieg hilft, wenn die Einleitung verwirrend ist. Hier ist sie klar. Konkrete Belege fehlen. Erstelle diese jetzt. Überarbeite die Einleitung, wenn spätere Rückmeldung dort ein Problem zeigt."}],bestOptionId:"write-evidence"}},carry:{takeaway:"Das Ergebnis darf dir wichtig sein. Probiere deinen machbaren Teil wirklich aus.",followUp:{questionId:"stoic-1-return",question:"Was hast du erstellt oder angefragt? Welche fehlende Unterstützung blieb ein Hindernis?",observationPrompt:"Benenne dein Arbeitsergebnis oder deine Bitte. Notiere, wenn der Schritt nicht möglich war.",adjustmentPrompt:"Welche Unterstützung oder welches Startsignal passt zum nächsten Versuch?"}},goDeeper:{sections:[{heading:"Anstrengung ausrichten, auch mit Hilfe Einfluss nehmen",paragraphs:["Die fachliche Darstellung zu Epiktet beschreibt Urteile, Ziele und Verhalten als Dinge, die bei uns liegen. Äußere Dinge wie Ansehen stellt sie dem gegenüber [S09]. Epiktet wurde in Hierapolis als versklavter Mensch geboren. Später lehrte er in Nikopolis. Arrian hielt seine Lehren fest. Diese Geschichte erklärt die Tradition, nicht die Wirksamkeit eines heutigen Arbeitsblatts. Die Unterscheidung kann Anstrengung ausrichten. Sie belegt nicht, dass Menschen Aufmerksamkeit, Gefühle oder Verhalten jederzeit vollständig willentlich steuern können.","ODA nutzt eine Anpassung mit Platz zwischen vollständiger Kontrolle und Hilflosigkeit: Was kannst du versuchen? Worauf kannst du mit Hilfe Einfluss nehmen? Was kannst du nicht allein bestimmen? Das Handbuch zur Stoic Week beschreibt die Unterscheidung nach Einfluss als Übung [S08]. Das ist Anleitung, keine Einzelstudie. Ein Problem am Arbeitsplatz kann gemeinsames Handeln brauchen. Ein Gesundheitsproblem kann Abklärung und Versorgung verlangen. Ein schädlicher Kontakt kann Schutz erfordern. Weil andere Menschen oder Umstände zum Ergebnis beitragen, ist das kein persönliches Versagen deiner Haltung."]},{heading:"Mach deinen Anteil sichtbar",paragraphs:["Gollwitzer und Sheeran werteten 94 unabhängige Planungsuntersuchungen mit 8.461 Teilnehmenden aus [S03]. Eine konkrete Situation mit einer beabsichtigten Reaktion zu verbinden verbesserte im Durchschnitt die Zielerreichung. Ziele, Designs und Vergleiche unterschieden sich. Die Studien beschränkten sich nicht auf moderne vorregistrierte randomisierte Versuche. Der standardisierte Effekt bedeutet keine prozentuale Erfolgschance. Er prüft weder das Sortieren nach Einfluss noch die Wirksamkeit des Stoizismus. Er garantiert auch nicht, dass ein Startsignal Müdigkeit oder fehlende Mittel überwindet.","Nutze diese Planungsform für einen kleinen Schritt: nach dem Mittagessen an deinem Arbeitsplatz einen brauchbaren Satz als Beleg schreiben. Ein Dokument öffnen ist Vorbereitung. Eine Interviewantwort proben ist ebenfalls Vorbereitung. Benenne sie so und wähle eine spätere Gelegenheit, sie zu nutzen. Eine Antwort von außen ist keine Bedingung fürs Erledigen. Halte passende Rückmeldung trotzdem fest. Verwirf sie nicht als „außerhalb meiner Kontrolle“. Der nächste Plan soll vorhandene Informationen, nötige Unterstützung und deine gewählte Lebensrichtung berücksichtigen."]}],sourceIds:["stoic-epictetus-iep","stoic-week-handbook","stoic-planning"]}},{schemaVersion:2,revision:2,id:"stoic-2",courseId:"stoic",locale:"de",title:"Ihr Schweigen beantwortet deine Frage noch nicht",goal:"Prüfe eine Deutung. Nutze dann eine begründete Rückfrage oder einen schützenden Schritt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Die Antwort kommt spät. Handelst du nach Tatsachen oder nach deiner Vermutung über den Grund?",reason:{id:"stoic-2-reason",label:"Was hast du wegen dieser ungeprüften Deutung getan?",kind:"text",maxLength:160,optional:!0,suggestions:["Eine echte Frist klären","Nicht mehr nach einer Vermutung handeln","Eine nötige Grenze schützen"]},why:{id:"stoic-2-why",label:"Was hast du wegen dieser ungeprüften Deutung getan?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Eine fehlende Antwort ist eine Tatsache. „Die respektieren mich nicht“ ist eine Deutung. Dafür braucht es vielleicht Belege. Das heißt nicht, dass das Ereignis nicht wehtun kann. Senecas Beschreibung von Zorn trennte die unwillkürliche erste Reaktion von späterer Zustimmung. Das war Philosophie, keine vollständige wissenschaftliche Erklärung von Belastung.","Komm zu demselben Ziel und Schritt zurück. Prüfe Belege für und gegen eine Geschichte, die dich dabei blockiert. Eine faire Alternative kann sein: „Ich weiß es noch nicht.“ Kläre dann eine echte Frist, berichtige eine falsche Angabe oder schütze eine Grenze. Tatsächliche schlechte Behandlung bleibt sichtbar. Weniger Ärger ist kein Muss. Die begründete Reaktion ist der Versuch."],example:{title:"Daniel prüft die fehlende Antwort",text:"Am Dienstag sieht Daniel am Schreibtisch zwei unbeantwortete Anfragen nach einer Referenz. Er vermutet, sein Kollege halte seine Arbeit für schwach. Den Grund kann er nicht prüfen, aber die Frist steht fest. Er fragt per Nachricht, ob die Referenz bis Donnerstag kommen kann. Bis zum Abend antwortet der Kollege nicht. Daniel notiert die Frage und die Unsicherheit."}},move:{invitation:"Prüfe eine Geschichte und mach dann einen begründeten nächsten Schritt.",instructions:["Benenne Tatsache und Deutung getrennt voneinander.","Nutze eine Rückfrage, eine sachliche Korrektur oder eine sichere Grenze."],prompts:[],suggestions:{action:["Eine sachliche Rückfrage zu meinem Ziel senden","Einen Fehler im Projekt anhand der Belege korrigieren","Um eine sichere Grenze bitten"],minimum:["Eine klare Frage zur Frist senden","Einen korrigierten Satz verfassen","Eine konkrete sichere Grenze aussprechen"],cue:["Vor meiner nächsten Antwort","Beim nächsten Projektaustausch","Wenn die Frist geklärt werden muss"],place:["In einem sicheren Nachrichtenverlauf","An meinem gewohnten Arbeitsplatz","An einem zugänglichen privaten Ort"],minutes:[2,5],fallback:["Einen anderen sicheren Weg zur Klärung wählen","Bekannte Tatsachen nutzen, keine Motive vermuten","Vor weiterem Kontakt Unterstützung holen"],observation:["Meine Frage und die tatsächliche Antwort","Die falsche Angabe, die ich berichtigt habe","Die Grenze, die ich mitgeteilt habe"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Eine sachliche Rückfrage zu meinem Ziel senden",minimum:"Eine klare Frage zur Frist senden",minutes:2,cueHint:"Vor meiner nächsten Antwort",placeHint:"In einem sicheren Nachrichtenverlauf",obstacleHint:"Der Kontakt ist unsicher oder die andere Person antwortet nicht.",fallbackHint:"Einen anderen sicheren Weg zur Klärung wählen",observationHint:"Meine Frage und die tatsächliche Antwort"},stopRule:"Echter Schaden braucht Schutz. Ersetze Belege für schlechte Behandlung nicht durch eine tröstliche Vermutung.",accessibleAlternative:"Nutze deine gewohnte Kommunikation, eine sichere schriftliche Antwort oder Unterstützung statt Kontakt."},result:{question:"Hast du deine begründete Reaktion genutzt?",observationPrompt:"Was hast du tatsächlich mitgeteilt? Welche Antwort kam zurück?"},judgment:{primary:{id:"stoic-2-decision",scenario:"Ein Kollege hat zweimal eine Antwort zur Referenz versprochen und nicht geliefert. Daniel braucht sie bis Donnerstag. Für den Grund der Verzögerung hat er keine Belege.",question:"Welche Reaktion prüft die Geschichte und klärt die Frist?",options:[{id:"comfort-guess",text:"Annehmen, dass der Kollege überlastet ist, und weiter warten, damit die Beziehung angenehm bleibt.",feedback:"Überlastung ist möglich, aber weiterhin eine ungeprüfte Erklärung. Die versäumten Zusagen und die Frist brauchen eine sachliche Frage. Der Beweggrund des Kollegen darf dabei unbekannt bleiben."},{id:"withdraw-work",text:"Vorerst weniger mitarbeiten, damit der Kollege merkt, welche Folgen seine fehlenden Antworten haben.",feedback:"Eine Grenze kann nötig werden. Solange der Grund unbekannt ist, fügt weniger Mitarbeit zunächst eine weitere Annahme hinzu. Kläre Frist und Hindernis, bevor du über eine passende Grenze entscheidest."},{id:"clarify-deadline",text:"Die fehlenden Antworten benennen und fragen, ob Donnerstag machbar ist oder ein anderer Weg nötig wird.",feedback:"Das prüft fehlende Informationen und nimmt ein tatsächliches Muster ernst. Eine neutrale Alternative ist keine erzwungene Positivität. Halte die Antwort fest, auch Schweigen. Entscheide dann über nötige Unterstützung oder eine Grenze."}],bestOptionId:"clarify-deadline"}},carry:{takeaway:"Prüfe die Deutung und kümmere dich um die Tatsache. Eine angenehme Vermutung bleibt eine Vermutung.",followUp:{questionId:"stoic-2-return",question:"Haben neue Belege deine Deutung gestützt, infrage gestellt, offengelassen oder auf Schaden hingewiesen?",observationPrompt:"Welche Belege änderten sich? Ist der Beweggrund weiter unbekannt?",adjustmentPrompt:"Noch einmal klären, den Plan ändern oder Unterstützung holen?"}},goDeeper:{sections:[{heading:"Erste Reaktionen und geprüfte Deutungen",paragraphs:["Senecas Darstellung von Zorn trennt unwillkürliche erste Regungen von der Zustimmung, die mit vollem Zorn verbunden ist [S10]. Das ist eine historische philosophische Unterscheidung, kein vollständiges experimentelles Gefühlsmodell. Panik, Schmerz, Traumasymptome oder ein automatischer Gedanke beweisen keine falsche Wahl. Tatsächliche Ereignisse, Umstände und Deutungen können alle eine Rolle spielen. Eine Deutung anzuschauen ist ein praktischer Blickwinkel. Es ist keine ausschließliche Erklärung dafür, warum ein Mensch leidet.","Das Gedankenprotokoll des NHS bietet sieben Fragen: Situation, Gefühle, Gedanke, Belege dafür, Belege dagegen, realistische Alternative und Gefühle danach [S11]. Beide Seiten zählen. Eine Alternative darf neutral statt beruhigend sein. Im Beispiel hält „Die Frist wurde verpasst und ich weiß nicht warum“ sowohl Problem als auch Unsicherheit sichtbar. ODAs kurze Prüfung mit einem Schritt vereinfacht diese Anleitung. Sie bildet keine Therapie nach. Die Gefühle danach müssen sich auch nicht verbessern."]},{heading:"Ähnlichkeit mit Therapie überträgt keine Wirksamkeit",paragraphs:["Hofmann und andere fanden 269 Metaanalysen und besprachen 106 repräsentative Arbeiten in ihrem Überblick zur kognitiven Verhaltenstherapie [S01]. Sie beschrieben erhebliche störungsspezifische Belege, besonders für mehrere angstbezogene Erkrankungen, Zorn und allgemeinen Stress. Einen Gesamteffekt oder eine Gesamtteilnehmerzahl für die gesamte KVT gab es nicht. Diese Befunde gehören zu den untersuchten Behandlungen. Sie gelten nicht für jede Übung, die einem Behandlungsgedanken ähnelt. Eine philosophische Lektion zu lesen liefert keine klinische KVT.","Ein Gedankenprotokoll ist eine offiziell beschriebene Selbsthilfeanleitung [S11]. Diese Quelle belegt aber keine einzelne klinische Effektgröße. Nutze es, um Belege und Deutung zu trennen und passend zu reagieren. Mach nicht aus jeder späten Nachricht einen Denkfehler. Deute Misshandlung nicht als harmlos um. Ist die Belastung stark, anhaltend oder beeinträchtigt sie deinen Alltag, kann fachliche Unterstützung der passende Schritt sein. Der Eintrag darf unveränderten Ärger, eine sachliche Klärung oder eine schützende Wahl enthalten. Nichts davon macht die Lektion zum Misserfolg."]}],sourceIds:["stoic-seneca-iep","stoic-thought-record","stoic-cbt"]}},{schemaVersion:2,revision:2,id:"stoic-3",courseId:"stoic",locale:"de",title:"Wieder dieselbe Unterbrechung? Hab einen nächsten Schritt bereit",goal:"Nutze eine realistische Reaktion auf ein Hindernis, damit dein bestehender nützlicher Schritt machbar bleibt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dein Plan passt, wenn der Tag mitspielt. Was tust du, wenn die bekannte Unterbrechung kommt?",reason:{id:"stoic-3-reason",label:"Welches echte Hindernis braucht diesmal eine Antwort?",kind:"text",maxLength:160,optional:!0,suggestions:["Nach der üblichen Unterbrechung weitermachen","Eine kurze Arbeitszeit schützen","Um Hilfe beim Zugang bitten"]},why:{id:"stoic-3-why",label:"Welches echte Hindernis braucht diesmal eine Antwort?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Schwierigkeiten vorstellen und eine Reaktion planen sind verschiedene Dinge. Die Planungsforschung verbindet ein konkretes Hindernis oder eine Gelegenheit mit einem machbaren Schritt. Sie belegt nicht, dass lebhafte negative Bilder dich widerstandsfähig machen. Hier zählt eine Reaktion, die du tatsächlich nutzen könntest. Eine schlimmere vorgestellte Szene ist dafür kein Wirksamkeitsbeleg.","Behalte Richtung und Schritt deines Versuchs. Wähle aus deinen Einträgen eine milde, realistische Schwierigkeit. Schreib eine Wenn-dann-Reaktion und nutze sie bei Bedarf. Bilder sind freiwillig. Durchlebe weder Katastrophen noch Trauma erneut. Kommt das Hindernis nicht, halte für diese Reaktion „Keine Gelegenheit“ fest. Einen gewöhnlichen Aufgabenversuch erfasst du getrennt davon."],example:{title:"Daniel macht nach dem Anruf weiter",text:"Vor der Arbeit an seiner Arbeitsprobe am Mittwoch plant Daniel für den Anruf, der oft die Mittagspause unterbricht. Nach dem Gespräch will er weitermachen und ein Projektergebnis in einem brauchbaren Satz beschreiben. Der Anruf kommt am Schreibtisch. Danach kehrt er zurück, diktiert den Satz und speichert ihn. Weiter kommt er an diesem Nachmittag nicht. Er hält aber die tatsächlich genutzte Reaktion fest."}},move:{invitation:"Bereite eine realistische Antwort auf eine Schwierigkeit bei deinem bestehenden Schritt vor.",instructions:["Benenne ein wahrscheinliches Hindernis ohne lebhafte Bilder.","Nutze die Reaktion bei Bedarf und halte sie danach fest."],prompts:[],suggestions:{action:["Nach einer Unterbrechung wie geplant weitermachen","Um eine machbare Grenze für die Projektarbeit bitten","Bei Zugangsproblemen meine Unterstützung nutzen"],minimum:["Ein Projektergebnis in einem brauchbaren Satz beschreiben","Eine konkrete Bitte um eine Grenze äußern","Konkret um den nötigen Zugang bitten"],cue:["Wenn die übliche Unterbrechung endet","Vor meiner freigehaltenen Arbeitszeit","Wenn das Zugangsproblem auftritt"],place:["An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf","An einem für mich zugänglichen Ort zum Planen"],minutes:[2,5],fallback:["Den nützlichen Satz diktieren","Die nächste machbare Arbeitsgelegenheit wählen","Eine vertraute Person um Hilfe bitten"],observation:["Ob Unterbrechung und Neustart stattfanden","Ob ich meine Reaktion genutzt habe","Das brauchbare Ergebnis meiner Arbeit"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Nach einer Unterbrechung wie geplant weitermachen",minimum:"Ein Projektergebnis in einem brauchbaren Satz beschreiben",minutes:2,cueHint:"Wenn die übliche Unterbrechung endet",placeHint:"An meinem gewohnten Arbeitsplatz",obstacleHint:"Für die Reaktion fehlen mir Zeit oder Zugang.",fallbackHint:"Den nützlichen Satz diktieren",observationHint:"Ob Unterbrechung und Neustart stattfanden"},stopRule:"Lass die Augen offen, wenn du möchtest. Beende oder überspringe die Übung bei Panik, Dissoziation oder aufdrängenden Erinnerungen.",accessibleAlternative:"Plane ohne Bilder. Wähle einen kleineren Schritt, praktische Unterstützung oder eine sichere Pause."},result:{question:"Hast du deine Reaktion bei Bedarf genutzt?",observationPrompt:"Kam das Hindernis? Was hast du tatsächlich getan?"},judgment:{primary:{id:"stoic-3-decision",scenario:"Daniels Zeitfenster für die Arbeitsprobe mittags wird oft durch einen kurzen nötigen Anruf unterbrochen. In der früheren Zeit hat er Betreuungsaufgaben. Nach dem Anruf bleiben meist zwei Minuten. Der Beleg wird heute Abend gebraucht.",question:"Welche Reaktion passt zu diesem vorhersehbaren Hindernis?",options:[{id:"restart-small",text:"Den nötigen Anruf annehmen und danach einen nützlichen Satz schreiben, sobald er beendet ist.",feedback:"Das berücksichtigt den nötigen Anruf und die verbleibende Zeit. Die Reaktion ist machbar und sichtbar. Halte fest, ob das Hindernis auftrat und ob du tatsächlich wieder angefangen hast."},{id:"same-minimum-tomorrow",text:"Stattdessen morgen zwei Minuten an der Arbeitsprobe arbeiten, damit die Mittagspause nach dem nötigen Anruf frei bleibt.",feedback:"Den kleinen Schritt zu verschieben kann Erholung schützen, wenn Zeit oder Kraft fehlen. Hier bleiben zwei Minuten und der Beleg wird heute gebraucht. Probiere jetzt, wieder anzufangen. Passe den Schritt an, wenn sich deine Kräfte verändern."},{id:"move-before-lunch",text:"Die Arbeit an der Arbeitsprobe vor das Mittagessen legen und den nötigen Anruf von dort aus annehmen.",feedback:"Eine frühere Zeit könnte die Unterbrechung umgehen, wenn sie frei wäre. Hier hat er in dieser Zeit Betreuungsaufgaben. Nimm den nötigen Anruf an und prüfe den nützlichen Satz in der verbleibenden Mittagspause."}],bestOptionId:"restart-small"}},carry:{takeaway:"Bereite eine wirklich nutzbare Reaktion vor, keine Katastrophe zum wiederholten Durchspielen.",followUp:{questionId:"stoic-3-return",question:"Kam das erwartete Hindernis? War deine Reaktion dann möglich?",observationPrompt:"Benenne das Hindernis, die verfügbare Zeit zum Weitermachen und deine Reaktion. Notiere, wenn sie ungeprüft blieb.",adjustmentPrompt:"Die Reaktion behalten, verkleinern oder das Umfeld ändern?"}},goDeeper:{sections:[{heading:"Antike Vorbereitung auf Widrigkeiten und heutige Planung",paragraphs:["Das Handbuch zur Stoic Week beschreibt das Nachdenken über Widrigkeiten als Übung [S08]. Das ist eine Praxisanleitung. Sie belegt keinen einzelnen Effekt negativer Zukunftsbilder. Ihre Begründung darf weder als nachgewiesener Mechanismus noch als Erlaubnis für eine allein durchgeführte Konfrontationstherapie dienen. ODA bietet stattdessen ein mildes Alltagshindernis, freiwillige Bilder und eine machbare Reaktion. Diese Änderungen sind Anpassungen. Du kannst ganz mit Worten planen, ohne eine belastende Erinnerung noch einmal aufzusuchen.","Einzelne Wenn-dann-Pläne verbinden eine konkrete Situation mit einem beabsichtigten Verhalten [S03]. Die Auswertung von 2006 umfasste 94 unabhängige Untersuchungen mit 8.461 Teilnehmenden. Sie fand durchschnittliche Vorteile für Zielerreichung in unterschiedlichen Kontexten. Sie zeigte nicht, dass ein aufgeschriebener Plan Müdigkeit, Behinderung oder fehlende Mittel überwindet. Deine Antwort kann eine kleinere nützliche Aufgabe, eine Grenze oder Unterstützung sein. Ist das Hindernis Gefahr, kümmere dich um Sicherheit statt ums Durchhalten. Beende eine Bilderübung bei Panik, Dissoziation oder aufdrängenden Erinnerungen. Ein Plan ohne Bilder bleibt möglich."]},{heading:"Das Hindernis liegt nicht immer in dir",paragraphs:["Wang und andere werteten mentales Kontrastieren mit Wenn-dann-Plänen aus [S04]. Die Abfolge verbindet einen machbaren Wunsch, das gewünschte Ergebnis, ein heutiges Hindernis und eine Wenn-dann-Reaktion. In 21 Artikeln mit 24 unabhängigen Schätzungen und 15.907 Teilnehmenden verbesserte sich die Zielerreichung im Durchschnitt mäßig: g = 0,336. Studien und Durchführung unterschieden sich erheblich, die Qualität war uneinheitlich. Das belegt weder einen optimalen Zweiminutenumfang noch negative Bilder allein oder diese ODA-Fassung.","Ein nötiger Anruf, fehlende Fahrt, eine Betreuungsaufgabe oder unzugängliche Ausstattung sind echte Bedingungen. Sie sind nicht bloß ein Haltungsproblem. Benenne sie genau. Deine Antwort kann sein, um Hilfe zu bitten, die Gelegenheit zu ändern oder einen ungeeigneten Plan zu beenden. Prüfe eine Bedingung, statt mehrere neue Rituale hinzuzufügen. Trenne Vorbereitung und Nutzung: Ein aufgeschriebener Neustartplan beweist keinen Neustart. Ohne Unterbrechung wurde der Ersatzschritt nicht geprüft. Halte diese Unsicherheit fest und erfasse den gewöhnlichen Schritt für sich."]}],sourceIds:["stoic-week-handbook","stoic-planning","stoic-mcii"]}},{schemaVersion:2,revision:2,id:"stoic-4",courseId:"stoic",locale:"de",title:"Die scharfe Antwort steht. Hilft sie dir?",goal:"Nutze freiwillig deinen Namen zum Nachdenken. Antworte dann sachlich so, dass es deiner gewählten Richtung dient.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"Deine Retourkutsche steht schon. Welche Antwort hilft deinem Ziel noch, wenn diese zehn Sekunden vorbei sind?",reason:{id:"stoic-4-reason",label:"Was würde eine sachliche Antwort schützen oder voranbringen?",kind:"text",maxLength:160,optional:!0,suggestions:["Nützliche Zusammenarbeit schützen","Falsche Angaben richtigstellen","Eine klare Grenze behalten"]},why:{id:"stoic-4-why",label:"Was würde eine sachliche Antwort schützen oder voranbringen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Deinen Namen zu nutzen kann beim kurzen Nachdenken Abstand schaffen. Experimente haben das untersucht. Breitere Forschung zeigt mäßige, unterschiedliche Effekte. Ruhe ist nicht garantiert. Dich aus dem All zu betrachten oder zehn Jahre vorauszudenken sind andere Übungen. Ihr eigener Nutzen ist hier nicht nachgewiesen.","Nutze diese Hilfe, wenn ein hitziger Moment dich von deinem Ziel abhält. Freiwillige Vorbereitung für 60 Sekunden: „Daniel, welche Angabe braucht eine Korrektur? Welche Bitte würde helfen?“ Nutze deinen Namen oder überspringe es. Nutze dann einen sachlichen Satz, eine Bitte oder eine Grenze. Abstand darf Schaden nicht ausblenden. Halte die Reaktion fest, auch wenn der Ärger bleibt."],example:{title:"Daniel kommt zu den Tatsachen zurück",text:"Im sicheren Projektgespräch am Donnerstag hört Daniel, seine Checkliste habe eine Verzögerung verursacht. Er möchte zurückschießen. Er fragt sich mit seinem Namen, was der Arbeit hilft. Dann nennt er das tatsächliche Übergabedatum und fragt, welcher Schritt geändert werden muss. Der Kollege bleibt verärgert. Daniel notiert seinen Satz und seine Bitte. Er behauptet nicht, der Konflikt sei gelöst."}},move:{invitation:"Nutze bei Bedarf Abstand und komm dann zu einem sachlichen Schritt zurück.",instructions:["Sprich dich bei Bedarf 60 Sekunden mit deinem Namen an. Das ist Vorbereitung.","Nutze einen sachlichen Satz, eine Bitte oder eine sichere Grenze."],prompts:[],suggestions:{action:["Eine falsche Angabe berichtigen und eine Bitte äußern","Eine klare Grenze für die Projektarbeit aussprechen","Eine begründete Frage zur Klärung stellen"],minimum:["Einen sachlichen Satz nutzen","Eine konkrete sichere Grenze aussprechen","Eine klare Frage senden"],cue:["Vor meiner nächsten hitzigen Antwort","Wenn sich falsche Vorwürfe wiederholen","Beim nächsten sicheren Projektaustausch"],place:["An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf","Im sicheren Besprechungsraum"],minutes:[2,5],fallback:["Sicher und sachlich per Nachricht antworten","Den Kontakt pausieren und Unterstützung holen","Eine andere sichere Gelegenheit wählen"],observation:["Der Satz, den ich tatsächlich genutzt habe","Meine Bitte und die tatsächliche Antwort","Ob die Grenze noch Unterstützung braucht"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Eine falsche Angabe berichtigen und eine Bitte äußern",minimum:"Einen sachlichen Satz nutzen",minutes:2,cueHint:"Vor meiner nächsten hitzigen Antwort",placeHint:"An meinem gewohnten Arbeitsplatz",obstacleHint:"Der Austausch ist unsicher oder die Pause verstärkt die Belastung.",fallbackHint:"Sicher und sachlich per Nachricht antworten",observationHint:"Der Satz, den ich tatsächlich genutzt habe"},stopRule:"Wähle eine Alltagssituation. Beende oder überspringe die Übung bei Panik, Dissoziation oder aufdrängenden Erinnerungen.",accessibleAlternative:"Lass die Augen offen, überspringe die Reflexion, antworte sachlich mit Hilfe oder hol dir Unterstützung."},result:{question:"Hast du deine gewählte sachliche Reaktion genutzt?",observationPrompt:"Welche Antwort oder Grenze hast du genutzt? Was folgte daraus?"},judgment:{primary:{id:"stoic-4-decision",scenario:"Daniel bekommt in einem sicheren Gespräch wieder einen falschen Vorwurf. Das falsche Datum verzögert die nächste Übergabe. Er kennt das tatsächliche Datum. Nach einer kurzen Pause möchte er die Arbeit voranbringen und die Angaben richtigstellen.",question:"Welche Antwort nutzt Abstand, ohne das Problem zu umgehen?",options:[{id:"let-pass",text:"Den Vorwurf stehen lassen, damit das Team sich auf die Lieferung konzentrieren kann statt auf diesen Konflikt.",feedback:"Die Arbeit voranzubringen zählt. Schweigen lässt aber eine wichtige falsche Angabe unkorrigiert. Nenne das Übergabedatum und bitte um den nächsten Schritt. Setze bei Bedarf eine Grenze."},{id:"facts-request",text:"Das Übergabedatum nennen, fragen, was geändert werden muss, und bei weiteren Vorwürfen eine Grenze setzen.",feedback:"So wird aus Nachdenken ein passender Schritt. Eine sachliche Korrektur und Bitte schützen die Aufgabe. Ruhe ist dafür nicht nötig. Geht das Muster weiter, bleibt eine Grenze möglich."},{id:"separate-follow-up",text:"Ein eigenes Gespräch über die wiederholten Vorwürfe verlangen und das aktuelle Gespräch ohne Datumskorrektur fortsetzen.",feedback:"Ein eigenes Gespräch kann ein wiederkehrendes Muster angehen. Hier betrifft das falsche Datum auch die aktuelle Aufgabe. Korrigiere es jetzt kurz. Vereinbare danach bei Bedarf das umfassendere Gespräch."}],bestOptionId:"facts-request"}},carry:{takeaway:"Eine kurze Pause ist hilfreich, wenn sie dir eine nützliche Reaktion ermöglicht.",followUp:{questionId:"stoic-4-return",question:"Hat das Nachdenken mit deinem Namen geholfen, gestört oder sich unnötig angefühlt?",observationPrompt:"Was hast du genutzt oder übersprungen? Welche sachliche Reaktion folgte danach?",adjustmentPrompt:"Das Mittel behalten, weglassen oder mehr Unterstützung holen?"}},goDeeper:{sections:[{heading:"Was Studien zum Nachdenken mit dem eigenen Namen zeigen",paragraphs:["Kross und andere berichteten sieben Studien mit 585 Teilnehmenden [S05]. In Studie 1a dachten 56 Studierende 60 Sekunden über ein kürzlich belastendes Erlebnis nach. Sie verwendeten ihren Namen und Pronomen außerhalb der Ich-Form. Danach berichteten sie mehr Abstand zu sich selbst. Spätere Experimente untersuchten belastende soziale Aufgaben und Leistung. Die Ergebnisse dieser Experimente innerhalb eines Forschungsprogramms weisen in dieselbe Richtung. Es sind keine sieben unabhängigen klinischen randomisierten Studien oder Belege dafür, dass der eigene Name Angst behandelt.","Diese Lektion verändert die Aufgabe zu einer milden aktuellen Situation und ergänzt anschließend einen sachlichen Schritt. Das ist eine ODA-Anpassung, nicht der ursprüngliche Ablauf. Du brauchst weder eine schmerzhafte Erinnerung aufzurufen noch die Augen zu schließen oder dich aus dem All zu betrachten. Fühlt sich die Formulierung seltsam oder destabilisierend an, lass sie weg. Frag direkt, was die Aufgabe braucht. Antworte sicher schriftlich oder such Unterstützung. Die tatsächliche Reaktion ist ein eigener Schritt. Nur nachdenken oder einen Entwurf schreiben bleibt Vorbereitung."]},{heading:"Mäßige Effekte und kein Schlafversprechen",paragraphs:["Murdoch und andere fassten 25 Experimente in 17 Artikeln mit 2.397 Erwachsenen zusammen [S06]. Der Gesamteffekt von Abstand zu sich selbst war mäßig: g = 0,19, mit einem 95%-Konfidenzintervall von 0,05 bis 0,33. Die Qualität der Belege war unklar. Die Teilnehmenden waren überwiegend jung und offenbar gesund. Ergebnisse unterschieden sich erheblich. Das Vorhersageintervall schloss null ein. Für objektive Ergebnisse aus vier Experimenten gab es keine statistisch signifikanten Effekte. Das belegt weder Überlegenheit bei stärker belasteten Menschen noch eine eigene Wirkung von kosmischen Bildern oder Zehnjahresbildern.","Eine vorregistrierte Reflexionsstudie stützte Abstand nicht als Schlafmaßnahme [S16]. Die Veränderung der Schlafqualität fiel zugunsten der Ich-Perspektive aus. Der Unterschied in der Schlafdauer war nicht signifikant. Ungleich verteilte Ausschlüsse erschwerten die Deutung. Tabelle und Text zum Wohlbefinden hatten widersprüchliche Vorzeichen. Eine Richtungsaussage ist hier deshalb nicht gerechtfertigt. Wähle dieses Mittel für einen freiwilligen Perspektivwechsel, nicht für besseren Schlaf oder verlässliche Erleichterung. Nimm das Problem weiter ernst. Prüfe den praktischen Nutzen daran, ob es einen begründeten Schritt erleichtert."]}],sourceIds:["stoic-kross-self-talk","stoic-kross-distancing","stoic-distancing-sleep"]}},{schemaVersion:2,revision:2,id:"stoic-5",courseId:"stoic",locale:"de",title:"Ein holpriger Versuch beschreibt nicht deinen ganzen Charakter",goal:"Schau fair auf deinen letzten Versuch und nutze bei der nächsten Gelegenheit eine konkrete Korrektur.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du spielst den Fehler immer wieder durch? Finde eine Änderung, die dein nächster Versuch tatsächlich nutzen kann.",reason:{id:"stoic-5-reason",label:"Welche konkrete Bedingung muss sich ändern, statt alles noch einmal durchzuspielen?",kind:"text",maxLength:160,optional:!0,suggestions:["Aus dem tatsächlichen Versuch lernen","Eine praktische Korrektur vornehmen","Nicht meinen ganzen Charakter beurteilen"]},why:{id:"stoic-5-why",label:"Welche konkrete Bedingung muss sich ändern, statt alles noch einmal durchzuspielen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Der Abendrückblick im stoischen Handbuch fragt: Was ging schief? Was lief gut? Was könnte sich ändern? Das ist eine beschriebene Anleitung, keine unabhängig nachgewiesene Behandlung oder Schlafhilfe. Bleib konkret. „Ich habe den vereinbarten Termin verpasst“ ermöglicht eine Korrektur. „Ich bin nutzlos“ liefert keinen hilfreichen nächsten Schritt.","Nutze den jüngsten Eintrag deines Versuchs. Behalte einen Teil, der seinen Zweck erfüllt hat. Ändere eine Bedingung, die nicht passte. Nutze diese Korrektur dann im nächsten Schritt. Zurückschauen ist Lernen oder Vorbereitung. Es bedeutet nicht, dass die spätere Handlung stattgefunden hat. Lass ein eigenes Abendritual weg, wenn der bestehende Rückblick reicht."],example:{title:"Daniel nutzt seinen Rückblick",text:"Am Freitagmittag schaut Daniel am Schreibtisch auf das Gespräch vom Donnerstag zurück. Er hat das Datum korrigiert, aber den belegenden Hinweis vergessen. Die Korrektur erkennt er an. Er wählt eine Änderung: In die Folgemeldung kommt ein Satz mit dem fehlenden Beleg. Er sendet sie am Nachmittag. Die Meinungsverschiedenheit bleibt. Sein Eintrag trennt den Rückblick von der tatsächlich gesendeten korrigierten Nachricht."}},move:{invitation:"Wähle anhand deines letzten Eintrags eine Korrektur und probiere sie aus.",instructions:["Benenne einen nützlichen Teil und eine konkrete Sache, die nicht passte.","Nutze im nächsten Schritt eine Korrektur."],prompts:[],suggestions:{action:["Eine Korrektur aus meinem Rückblick im Projekt umsetzen","Eine passende Wiedergutmachung aus meinem Eintrag umsetzen","Das geänderte Startsignal für meinen Schritt nutzen"],minimum:["Einen korrigierten Projektsatz senden","Konkret um eine Wiedergutmachung bitten","Ein Projektergebnis in einem brauchbaren Satz beschreiben"],cue:["Bei meiner nächsten Projektrückmeldung","Bei meiner nächsten sicheren Gelegenheit zur Wiedergutmachung","Beim neu gewählten Startsignal"],place:["In einem sicheren Nachrichtenverlauf","An meinem gewohnten Arbeitsplatz","An einem für mich zugänglichen Ort zum Planen"],minutes:[2,5],fallback:["Eine kleinere sachliche Korrektur nutzen","Eine andere sichere Gelegenheit wählen","Unterstützung holen statt alles wieder durchspielen"],observation:["Die tatsächlich genutzte Korrektur","Was die geänderte Bedingung ermöglicht hat","Meine Bitte und die tatsächliche Antwort"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Eine Korrektur aus meinem Rückblick im Projekt umsetzen",minimum:"Einen korrigierten Projektsatz senden",minutes:2,cueHint:"Bei meiner nächsten Projektrückmeldung",placeHint:"In einem sicheren Nachrichtenverlauf",obstacleHint:"Der Rückblick wiederholt sich oder die Korrektur ist unsicher.",fallbackHint:"Eine kleinere sachliche Korrektur nutzen",observationHint:"Die tatsächlich genutzte Korrektur"},stopRule:"Beende, kürze oder verlege Rückblicke, die Grübeln verstärken oder den Schlaf stören. Schütze deine Sicherheit.",accessibleAlternative:"Nutze einen kurzen gesprochenen oder unterstützten Rückblick, den gespeicherten Rückblick oder Unterstützung statt eines weiteren Rituals."},result:{question:"Hast du deine gewählte Korrektur genutzt?",observationPrompt:"Was hast du im tatsächlichen Schritt geändert?"},judgment:{primary:{id:"stoic-5-decision",scenario:"Daniels Arbeitszeit am Abend fiel zweimal aus, weil Betreuungsaufgaben länger dauerten. Er möchte weiterhin ein Beispiel für seine Projektarbeit festhalten. Mittags hat er am Schreibtisch zwei sichere Minuten.",question:"Was macht den Rückblick nützlich?",options:[{id:"same-plan",text:"Die späten Betreuungsaufgaben festhalten und die Abendzeit wiederholen, um mehr Regelmäßigkeit aufzubauen.",feedback:"Der Eintrag ist ehrlich. Die Bedingung hat aber wiederholt nicht funktioniert. Behalte die Richtung und prüfe das verfügbare Minimum mittags, statt erneut auf dieselbe ungeeignete Zeit zu setzen."},{id:"make-up",text:"Die verpasste Zeit festhalten und fürs Wochenende eine längere Einheit planen, um die Arbeit nachzuholen.",feedback:"Eine längere Einheit kann helfen, wenn sie machbar ist. Sie prüft aber nicht das wiederkehrende Problem mit dem Startsignal. Probiere die kleine verfügbare Zeit, bevor du zusätzliche Anforderungen zum Ausgleich hinzufügst."},{id:"cue-change",text:"Seine Betreuungsverpflichtung anerkennen und beim verfügbaren Startsignal mittags einen Satz über sein Projektergebnis schreiben.",feedback:"Das benennt eine echte Grenze, bewahrt seinen geleisteten Beitrag und ändert eine Bedingung. Der Rückblick ist getrennt vom nächsten Versuch. Halte fest, ob der Schritt mittags tatsächlich stattfindet."}],bestOptionId:"cue-change"}},carry:{takeaway:"Ändere nach einem fairen Rückblick eine Bedingung. Prüfe sie dann beim nächsten Schritt.",followUp:{questionId:"stoic-5-return",question:"Wurde deine geänderte Bedingung geprüft? Was hat sie ermöglicht?",observationPrompt:"Benenne Korrektur und Schritt oder halte fest, dass die Bedingung ungeprüft blieb.",adjustmentPrompt:"Die Korrektur behalten, das Startsignal ändern oder Unterstützung suchen?"}},goDeeper:{sections:[{heading:"Der Rückblick ist eine Anleitung, kein Urteil",paragraphs:["Das Handbuch zur Stoic Week beschreibt fünf bis zehn Minuten Abendrückblick vor dem Zubettgehen [S08]. Die drei Fragen lauten: Was ging schief? Was lief gut? Was könnte anders sein? Es empfiehlt, dich so fair einzuschätzen wie einen Freund. Das ist ein dokumentierter Praxisablauf. Es ist weder ein empirisch bestätigter optimaler Umfang noch eine Studie zum Rückblick allein. Ein kürzerer ODA-Rückblick oder ein Rückblick früher am Tag sind Anpassungen.","Schau auf den gewählten Versuch, statt deinen ganzen Charakter vor Gericht zu stellen. Halte einen sichtbaren Fehler, einen nützlichen Beitrag und eine konkrete Änderung fest. Erzwinge weder Vergebung noch Entschuldigung oder ein warmes Gefühl. Wiedergutmachung passt, wenn du Schaden verursacht hast. Schutz kann passen, wenn dir geschadet wurde. Wird der Rückblick strafend, wiederholt er sich oder stört er den Schlaf, kürze, verlege oder beende ihn. Hier geht es um eine umsetzbare Korrektur. Garantierte Erleichterung oder eine weitere Abendpflicht gibt es nicht."]},{heading:"Direkte Stoizismusforschung gibt es, mit Grenzen",paragraphs:["Direkte kontrollierte Forschung zu stoischem Training ist noch vorläufig. Maclellan und Derakshan verteilten 45 Menschen mit starken Sorgen zufällig auf stoisches Training mit acht Einheiten, kombiniertes Training und eine aktive Kontrollgruppe [S13]. Die Zusammenfassung berichtete Veränderungen bei Grübeln und Selbstwirksamkeit. Sie zeigt nicht, welcher Bestandteil half oder ob ein einzelner Abendrückblick diagnostizierte Angst behandelt. Eine kleine Trainingsstudie sagt dir nicht, dass wiederholte Rückblicke Symptome zuverlässig verändern.","Kings Dissertation von 2025 teilte 119 Erwachsene aus einer nichtklinischen Stichprobe einem zweiwöchigen stoischen Onlinetraining oder einer Warteliste zu [S15]. Die Hochschulzusammenfassung berichtete günstige Veränderungen bei einigen Messwerten zur psychischen Gesundheit bei Teilnehmenden mit vollständigen Daten. Eine unveröffentlichte Dissertation mit Wartelistenvergleich liefert frühe Hinweise, keinen fachlich begutachteten Konsens. Keine der beiden Studien zeigt, dass diese kurze ODA-Anpassung das Training nachbildet. Probiere eine faire Korrektur, wenn sie passt. Halte den Verlauf fest. Such fachliche Hilfe, wenn Belastung anhält oder deinen Alltag beeinträchtigt. Der Eintrag soll eine tatsächlich geänderte Bedingung und einen wirklich versuchten Schritt benennen. Ein neuer Plan allein lässt die Korrektur ungeprüft."]}],sourceIds:["stoic-week-handbook","stoic-training-trial","stoic-training-thesis"]}},{schemaVersion:2,revision:2,id:"stoic-6",courseId:"stoic",locale:"de",title:"Die Woche war voll. Kam dein Wichtigstes dran?",goal:"Nutze deine Einträge, um nächste Woche einen nützlichen Schritt und eine machbare Bedingung beizubehalten.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Die Woche war voll. Welche deiner tatsächlichen Handlungen passte zu deinem Ziel?",reason:{id:"stoic-6-reason",label:"Was bekommt weniger Zeit, damit dein Wichtigstes Platz hat?",kind:"text",maxLength:160,optional:!0,suggestions:["Das nützliche Minimum behalten","Das hilfreiche Startsignal nutzen","Unnütze zusätzliche Rituale weglassen"]},why:{id:"stoic-6-why",label:"Was bekommt weniger Zeit, damit dein Wichtigstes Platz hat?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Eine leichte Aufgabe und einen passenden Schritt zu wählen sind verschiedene Dinge. Die Forschung zu mentalem Kontrastieren und Planung verbindet einen machbaren Wunsch, sein Ergebnis, ein echtes Hindernis und eine konkrete Reaktion. Durchschnittliche Vorteile sind mäßig und unterschiedlich. Die Methode garantiert keinen Erfolg. Sie macht auch nicht jedes Hindernis zu einem persönlichen Fehler.","Zieh aus deinem bisherigen Versuch Bilanz. Lies die tatsächlichen Einträge, auch ausgebliebene Gelegenheiten und Pausen. Behalte den nützlichen Schritt und das Startsignal. Ändere bei Bedarf eine Bedingung. Probiere dann das nächste Minimum. Lass Mittel weg, die nicht geholfen haben. Das Ergebnis bleibt ungewiss. Seine Rückmeldung kann den Plan trotzdem verändern. Unterstützung oder Aufhören bleiben berechtigte Möglichkeiten."],example:{title:"Daniel behält, was funktioniert hat",text:"Am Montagmittag der nächsten Woche prüft Daniel seine Einträge. Zwei brauchbare Sätze entstanden in der kurzen Zeit am Schreibtisch. Ein anderer Versuch endete wegen fehlendem Zugang. Er behält die Zeit, bittet um den fehlenden Zugang und beschreibt ein weiteres Projektergebnis in einem Satz. Zusätzliche Bilder lässt er weg. Die Bewerbung ist noch offen. Sein nächster Plan nutzt aber die beobachteten Bedingungen."}},move:{invitation:"Behalte den passenden Schritt. Wähle seine nächste machbare Gelegenheit.",instructions:["Nutze deine Einträge, um eine Bedingung zu behalten oder zu ändern.","Setze das nützliche Minimum um. Andere Mittel bleiben freiwillig."],prompts:[],suggestions:{action:["Wieder ein nützliches Beispiel für meine Projektarbeit festhalten","Meine begründete Rückfrage wiederholen","Um die laut Rückblick nötige Hilfe bitten"],minimum:["Ein Projektergebnis in einem brauchbaren Satz beschreiben","Eine klare Frage senden","Konkret um den nötigen Zugang bitten"],cue:["Wenn ich vom Mittagessen zurückkomme","Bei meiner nächsten sicheren Projektrückmeldung","Vor meinem nächsten Projektversuch"],place:["An meinem gewohnten Arbeitsplatz","In einem sicheren Nachrichtenverlauf","An einem für mich zugänglichen Ort zum Planen"],minutes:[2,5],fallback:["Meine erprobte kleinere Fassung nutzen","Die nächste zugängliche Gelegenheit wählen","Unterstützung holen oder den ungeeigneten Plan beenden"],observation:["Das passende Ergebnis meiner Arbeit","Ob mein gewähltes Startsignal kam","Was die geprüfte Bedingung ermöglicht hat"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}]},suggested:{action:"Wieder ein nützliches Beispiel für meine Projektarbeit festhalten",minimum:"Ein Projektergebnis in einem brauchbaren Satz beschreiben",minutes:2,cueHint:"Wenn ich vom Mittagessen zurückkomme",placeHint:"An meinem gewohnten Arbeitsplatz",obstacleHint:"Das bisherige Minimum oder Startsignal passt nicht mehr zu meinen Umständen.",fallbackHint:"Meine erprobte kleinere Fassung nutzen",observationHint:"Das passende Ergebnis meiner Arbeit"},stopRule:"Sicherheit und nötige Erholung haben Vorrang vor Durchhalten. Ändere, pausiere oder beende ungeeignete Pläne.",accessibleAlternative:"Behalte einen zugänglichen Schritt, nutze Hilfe oder wähle Unterstützung. Du musst nicht jedes Kursmittel weiterführen."},result:{question:"Hast du das nächste nützliche Minimum umgesetzt?",observationPrompt:"Was hast du tatsächlich getan? Welche Rückmeldung bleibt relevant?"},judgment:{primary:{id:"stoic-6-decision",scenario:"Daniel hat geprüft, welche Projektbeispiele zu den Anforderungen des Arbeitgebers passen. Bei einem passenden Beispiel fehlt noch ein Satz, der seine Projektarbeit beschreibt. Laut seinen Einträgen klappt Schreiben mittags. Heute hat er zehn Minuten.",question:"Welcher Schritt bringt sein gewähltes Ziel am direktesten voran?",options:[{id:"draft-relevant",text:"Beim erprobten Startsignal mittags ein passendes Projektergebnis in einem Satz beschreiben. Bei Bedarf einen zugänglichen Ersatzschritt nutzen.",feedback:"Das behält den passenden Schritt und eine durch seine Einträge gestützte Bedingung. Es schafft etwas Sichtbares, ohne eine Zusage zu versprechen. Halte den Versuch fest und nutze spätere Rückmeldung."},{id:"advice-read",text:"Zehn Minuten Bewerbungstipps lesen und nach weiteren Empfehlungen eine Aufgabe für die Belege wählen.",feedback:"Tipps helfen, wenn Informationen fehlen. Hier sind das nötige Beispiel und ein machbares Startsignal bekannt. Mehr Lesen verschiebt das passende Arbeitsergebnis, das in dieser Zeit entstehen könnte."},{id:"check-relevance-again",text:"Frühere Sätze über Projektergebnisse prüfen und den auswählen, der den Anforderungen des Arbeitgebers am nächsten kommt.",feedback:"Passung zu prüfen hilft bei unklaren Anforderungen oder Beispielen. Daniel hat sie bereits geprüft. Diesem Beispiel fehlt der Satz. Nutze die verfügbare Schreibzeit. Prüfe erneut, wenn die Anforderungen sich ändern."}],bestOptionId:"draft-relevant"}},carry:{takeaway:"Behalte den nützlichen Schritt und eine machbare Bedingung. Lass Rückmeldung deinen nächsten Versuch verbessern.",followUp:{questionId:"stoic-6-return",question:"Hat die gewählte Bedingung geholfen oder nicht funktioniert? Blieb sie ungeprüft, oder ist ihre Wirkung unklar?",observationPrompt:"Welche Bedingung trat ein? Welchen Schritt hast du tatsächlich versucht?",adjustmentPrompt:"Wiederholen, eine Bedingung ändern, Unterstützung holen oder aufhören?"}},goDeeper:{sections:[{heading:"Festigen heißt, passende Belege zu nutzen",paragraphs:["Epiktets Unterscheidung ist philosophische Orientierung für deine Anstrengung [S09]. Sie verlangt nicht, Ergebnisse deiner Handlung zu ignorieren. Eine Antwort, ein gescheiterter Zugangsweg oder ein wiederholter Konflikt können den nächsten Versuch beeinflussen. Du kannst die Entscheidung eines Arbeitgebers nicht allein bestimmen. Du kannst aber passende Rückmeldung nutzen und um Hilfe bitten. Dein Eintrag soll den Schritt und das relevante Ergebnis enthalten. Mach keines von beiden zu einem Urteil über deinen ganzen Charakter.","Die Forschung zu Wenn-dann-Plänen stützt die Verbindung einer erkennbaren Situation mit einer beabsichtigten Reaktion bei verschiedenen Zielen und Umgebungen [S03]. Das hilft nur, wenn die Reaktion machbar und passend ist. „Nach dem Mittagessen ein Projektergebnis in einem brauchbaren Satz beschreiben“ ist ein konkreter Schritt. „Nach dem Mittagessen den Arbeitgeber zur Zusage bringen“ ist ein äußeres Ergebnis. Vorbereitung oder Tipps lesen können passen. Benenne sie ehrlich. Die letzte Lektion festigt einen fortlaufenden Versuch. Sie führt kein weiteres Tagesritual ein. Ein abgeschlossener Kurs beweist keine Praxis im Alltag."]},{heading:"Ein Wunsch, ein Hindernis und eine machbare Reaktion",paragraphs:["Wang und andere werteten mentales Kontrastieren mit Wenn-dann-Plänen aus [S04]. Die Abfolge benennt einen machbaren Wunsch, das gewünschte Ergebnis, ein heutiges Hindernis und eine konkrete Wenn-dann-Reaktion. In 21 Artikeln mit 24 unabhängigen Schätzungen und 15.907 Teilnehmenden verbesserte sich die Zielerreichung durchschnittlich um g = 0,336, mit einem 95%-Konfidenzintervall von 0,229 bis 0,443. Die Unterschiede waren erheblich: I² = 59,3%. Die Studienqualität variierte. Das ist ein aktueller Schätzwert für die kombinierte Abfolge, keine allgemeine Erfolgsquote.","ODAs kurze Nutzung der Abfolge und der wöchentliche Rückblick auf die Einträge sind Anpassungen. Eine allgemeine Dosis oder Wirksamkeit für genau diesen Ablauf wurde nicht nachgewiesen. Wähle einen Schritt für dein tatsächliches Anliegen, statt bloßer Beschäftigung oder jeder Übung im Kurs. Ist das Hindernis äußere Gefahr, fehlende Mittel, Krankheit oder eine Betreuungsaufgabe, kann deine Antwort Unterstützung, eine Grenze, Erholung oder das Beenden des Ziels sein. Halte den nächsten Versuch getrennt von Plan und Rückblick fest. Unveränderte Gefühle und ein ungewisses äußeres Ergebnis löschen einen berichteten nützlichen Schritt nicht aus."]}],sourceIds:["stoic-epictetus-iep","stoic-planning","stoic-mcii"]}}],c=[{id:"stoic-1",practice:["Wähle ein Ziel. Trenne machbaren Schritt, nötige Unterstützung und äußere Ergebnisse.","Benenne eine erkennbare Gelegenheit und ein nützliches Minimum.","Setze den Schritt um oder benenne Vorbereitung und ihre spätere Nutzung ausdrücklich."],correct:1,photo:{id:"1507525428034-b723cf961d3e",alt:"Ein ruhiges Ufer, an dem klares Wasser auf Sand trifft"}},{id:"stoic-2",practice:["Trenne eine Tatsache von einer ungeprüften Deutung.","Prüfe Belege auf beiden Seiten, ohne echten Schaden zu verharmlosen.","Nutze eine begründete Rückfrage, eine sachliche Korrektur oder einen sicheren schützenden Schritt."],correct:2,photo:{id:"1500534314209-a25ddb2bd429",alt:"Schichten dunstiger Hügel in der Abenddämmerung"}},{id:"stoic-3",practice:["Wähle ein mildes realistisches Hindernis für deinen bestehenden Schritt. Bilder bleiben freiwillig.","Plane eine machbare Reaktion. Beende die Übung, wenn die Belastung wächst.","Nutze die Reaktion bei Bedarf. Halte fest, ob das Hindernis auftrat."],correct:1,photo:{id:"1464822759023-fed622ff2c3b",alt:"Bewaldete Täler unter verschneiten Bergen"}},{id:"stoic-4",practice:["Wähle eine milde Alltagssituation. Sprich dich freiwillig 60 Sekunden mit deinem Namen an.","Beende oder überspringe die Übung bei Panik, Dissoziation oder aufdrängenden Erinnerungen.","Nutze einen sachlichen Satz, eine Bitte oder eine sichere Grenze und halte es fest."],correct:0,photo:{id:"1506905925346-21bda4d32df4",alt:"Bergkämme von oben über einem Wolkenmeer gesehen"}},{id:"stoic-5",practice:["Schau auf einen tatsächlichen Versuch zurück. Benenne einen nützlichen Teil und etwas konkret Unpassendes.","Wähle eine Korrektur. Kürze, verlege oder beende einen strafenden oder schlafstörenden Rückblick.","Nutze die Korrektur in einem echten Schritt. Halte ihn getrennt vom Rückblick fest."],correct:1,photo:{id:"1475924156734-496f6cac6ec1",alt:"Wellen an einem felsigen Ufer in der Abenddämmerung"}},{id:"stoic-6",practice:["Vergleiche tatsächliche Versuche für dein bestehendes Ziel und deinen Schritt.","Behalte das nützliche Minimum. Ändere höchstens eine Bedingung.","Probiere den nächsten passenden Schritt. Halte ihn fest. Zusätzliche Mittel bleiben freiwillig."],correct:2,photo:{id:"1502082553048-f009c37129b9",alt:"Ein einzelner Baum in einer offenen Landschaft"}}],l={id:"stoic",title:"Schon wieder nachgeschaut? Gib deinem nächsten Schritt Platz",subtitle:"6 Lektionen: Trotz Ungewissheit handeln, Deutungen prüfen und einen machbaren Versuch in die nächste Woche mitnehmen.",description:"Wähle ein Ziel, das vor lauter Ungewissheit zu kurz kommt. Nutze stoische Unterscheidungen und freiwillige psychologische Hilfen für einen begründeten Schritt. Schau zurück und passe ihn an.",scope:"Für Erwachsene, die mit Stress, Rückschlägen und Ungewissheit verlässlicher umgehen möchten. Stoizismus heißt hier weder Gefühle unterdrücken noch Tapferkeit vorspielen. Gefühle sind willkommen. Die Übung betrifft das, was du als Nächstes tust. Das ist Lernen und eigenständiges Üben, keine Therapie und kein Behandlungsersatz. Lebst du mit Angst, Depression, Trauma oder aufdrängenden Sorgen, passen manche Übungen vielleicht nicht zu dir. Das gilt besonders fürs Vorstellen von Rückschlägen. Arbeite dafür bitte mit einer qualifizierten Fachperson. Bist du in einer Krise oder denkst daran, dir etwas anzutun, kontaktiere jetzt den örtlichen Notruf.",outcome:"Ein Versuch für dein Ziel mit tatsächlichen Schritten, ehrlichen Rückblicken und einem Plan für nächste Woche, der Unterstützung und Grenzen einschließt.",photo:{id:"1439066615861-d1af74d74000",alt:"Ein Holzsteg an einem stillen Bergsee"},lang:"de",lessons:a.map((e,h)=>{const t=c[h],n=e.judgment.primary,r=n.options.find(i=>i.id===n.bestOptionId),s=n.options.filter(i=>i.id!==n.bestOptionId).map(i=>i.text);return s.splice(t.correct,0,r.text),{...t,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${n.scenario} ${n.question}`,options:s,feedback:r.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})},u=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,SOURCES:d,STOIC_LESSONS_V2:a},Symbol.toStringTag,{value:"Module"}));export{u as s};
